import math
def gc(s): return sum(1 for c in s if c in 'GC')/len(s)
# change-point: maximize log-likelihood of 2 segments (low-high) or 3 segments
best=None
for i in range(50,L-100):
    for j in range(i+100,L-50):
        a=x[:i]; b=x[i:j]; c=x[j:]
        def ll(seg):
            if not seg: return 0
            p=sum(seg)/len(seg)
            if p in (0,1): p=0.001*abs(p-0.5)+ (0.001)  # avoid
            p=min(max(p,1e-3),1-1e-3)
            return sum(v*math.log(p) + (1-v)*math.log(1-p) for v in seg)
        tot=ll(a)+ll(b)+ll(c)
        if best is None or tot>best[0]:
            best=(tot,i,j)
print("best 3-seg:", best[1]+1, best[2], "GC:", round(gc(seq[:best[1]]),3), round(gc(seq[best[1]:best[2]]),3), round(gc(seq[best[2]:]),3))
