x=[1 if c in 'GC' else 0 for c in seq]
cum=[0]
for v in x: cum.append(cum[-1]+v)
def n1(i,j): return cum[j]-cum[i]
def ll_seg(n,l):
    if l==0: return 0
    p=min(max(n/l,1e-3),1-1e-3)
    return n*math.log(p)+(l-n)*math.log(1-p)
best=None
for i in range(0,L-100,10):
    for j in range(i+100,L,10):
        t = ll_seg(n1(0,i),i)+ll_seg(n1(i,j),j-i)+ll_seg(n1(j,L),L-j)
        if best is None or t>best[0]: best=(t,i,j)
print(best)
i,j=best[1],best[2]
print("segments GC:", round(n1(0,i)/i,3), round(n1(i,j)/(j-i),3), round(n1(j,L)/(L-j),3))
print(i+1,j)
